        "Prijedlog traži dativ: ab nächstem Monat, ab dem 1. Mai. Ispred vremenskih oznaka često stoji bez člana: ab Montag, ab morgen. Ab je i odvojivi prefiks: abfahren (otputovati, krenuti), abholen (pokupiti, doći po nekoga).",
