      "layout": "standardStudy",
      "translation": "s • sa",
      "explanation": [
        "Glavna ideja: mit je prijedlog s dativom, na hrvatskom „s, sa”. Označava osobu s kojom se nešto radi (mit dir — s tobom), sredstvo ili prijevoz (mit dem Bus — autobusom), instrument (mit dem Stift — olovkom) i dodatak (Kaffee mit Milch — kava s mlijekom).",
        "Nakon mit uvijek dolazi dativ: mit dem Mann, mit der Frau, mit dem Kind, mit den Freunden. Dativ množine obično ima nastavak -n.",
        "Kao odvojivi prefiks mit se nalazi u mnogim glagolima: mitkommen (ići s nekim), mitnehmen (uzeti sa sobom): Kommst du mit?"
      ],
      "examples": [
        {
          "de": "Ich komme mit dir.",
          "lv": "Idem s tobom."
        },
        {
          "de": "Ich fahre mit dem Bus.",
          "lv": "Vozim se autobusom."
        },
        {
          "de": "Sie schreibt mit dem Stift.",
          "lv": "Ona piše olovkom."
        },
        {
          "de": "Kommst du mit?",
          "lv": "Ideš li s nama?"
        },
        {
          "de": "Ich möchte Kaffee mit Milch.",
          "lv": "Htio bih kavu s mlijekom."
        }
      ],
      "comparison": [
        {
          "word": "ohne",
          "meaning": "bez",
          "example": "Kaffee ohne Zucker. – Kava bez šećera."
        },
        {
          "word": "bei",
          "meaning": "kod",
          "example": "Ich wohne bei meinen Eltern. – Živim kod roditelja."
        },
        {
          "word": "zusammen",
          "meaning": "zajedno",
          "example": "Wir lernen zusammen. – Učimo zajedno."
        }
      ],
      "tip": [
        "Mit + dativ, uvijek: mit mir, mit dir, mit ihm, mit uns.",
        "Prijevoz se izražava s mit: mit dem Zug, mit dem Auto, ali „pješice” je zu Fuß."
      ],
      "important": [
        "Mit nikad ne traži akuzativ: mit dem Bus (a ne „mit den Bus”).",
        "Kommst du mit? ne znači doslovno „dolaziš li s?”, nego „ideš li s nama?” — mitkommen ima odvojivi prefiks."
      ],
