      "explanation": [
        "Glavna misao: sicher je i pridjev i prilog. Kao pridjev znači siguran (bez opasnosti: ein sicherer Weg) ili uvjeren (Ich bin sicher). Kao prilog znači sigurno ili naravno: Er kommt sicher.",
        "Izraz sich (dativ) sicher sein znači biti uvjeren: Ich bin mir sicher. Komparativ i superlativ: sicherer, am sichersten; imenica je die Sicherheit.",
        "Na početku rečenice Sicher može biti i odgovor: Sicher! — Naravno!"
      ],
      "examples": [
        {
          "de": "Der Weg ist nachts nicht sicher.",
          "lv": "Put noću nije siguran."
        },
        {
          "de": "Ich bin mir ganz sicher.",
          "lv": "Potpuno sam siguran."
        },
        {
          "de": "Er kommt sicher heute noch.",
          "lv": "Sigurno će doći još danas."
        },
        {
          "de": "Das Kind fährt schon sicher Fahrrad.",
          "lv": "Dijete već sigurno vozi bicikl."
        },
        {
          "de": "Sicher, ich helfe dir gern.",
          "lv": "Naravno, rado ću ti pomoći."
        }
      ],
